(function () {
    var t = 'dental';
    try { var s = localStorage.getItem('sky-clinic-theme'); if (s === 'aesthetics' || s === 'estetics') { t = 'aesthetics'; if (s === 'estetics') localStorage.setItem('sky-clinic-theme', 'aesthetics') } } catch (e) { }
    try {
        var p = location.pathname.split('/').filter(Boolean);
        var lc = ['en', 'fr', 'de', 'el', 'it', 'es', 'sq'];
        if (p.length && lc.indexOf(p[0]) > -1) p = p.slice(1);
        if (p.length && (p[0] === 'aesthetics' || p[0] === 'estetics')) t = 'aesthetics';
    } catch (e) { }
    var d = t === 'aesthetics';
    var bg = d ? 'rgb(0,57,52)' : 'rgb(232,231,229)';
    var fg = d ? 'rgb(232,231,229)' : 'rgb(0,57,52)';
    var ac = d ? 'rgb(26,158,143)' : 'rgb(26,158,143)';
    var r = document.documentElement;
    r.style.setProperty('--nl-bg', bg);
    r.style.setProperty('--nl-fg', fg);
    r.style.setProperty('--nl-ac', ac);
    r.className = d ? 'theme-aesthetics' : 'theme-dental';
    var m = document.getElementById('meta-theme-color');
    if (m) m.setAttribute('content', d ? '#003934' : '#e8e7e5');
    var cs = document.getElementById('meta-color-scheme');
    if (cs) cs.setAttribute('content', d ? 'only dark' : 'only light');
    var scs = document.getElementById('meta-supported-cs');
    if (scs) scs.setAttribute('content', d ? 'dark only' : 'light only');
    r.style.colorScheme = d ? 'only dark' : 'only light';
    window.__initialTheme = t;
})();

